"""Summarize the preserved final JMH files without conflating row/document units."""
import argparse
import hashlib
import json
from pathlib import Path
from statistics import mean

WORKLOADS = ("ascii", "unicode", "repeat_identity", "repeat_equal_lmdb", "unique_lmdb", "wide",
             "medium", "medium_unicode", "long", "long_unicode", "long_latin1", "long_cjk",
             "long_emoji", "long_sparse", "query")
HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
REPO = ROOT.parent
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--prefix", default="final")
parser.add_argument("--include-small", action="store_true")
parser.add_argument("--include-memory", action="store_true")
args = parser.parse_args()


def metric(value):
    raw = value["rawData"]
    assert len(raw) == 2 and all(len(fork) == 5 for fork in raw), "Expected two forks, five measurements each"
    return {"mean": value["score"], "error_99_9": value["scoreError"],
            "confidence_99_9": value["scoreConfidence"], "fork_means": [mean(fork) for fork in raw],
            "raw_data": raw}


def pair(entries, label, unit, source):
    implementations = {r["params"]["implementation"]: r for r in entries}
    assert set(implementations) == {"published", "current"} and len(entries) == 2
    result = {"workload": label, "unit": unit, "source": source}
    for key, name in (("before", "published"), ("after", "current")):
        row = implementations[name]
        assert row["primaryMetric"]["scoreUnit"] == "ns/op"
        result[key] = {"time": metric(row["primaryMetric"]),
                       "allocation": metric(row["secondaryMetrics"]["gc.alloc.rate.norm"])}
    b, a = result["before"], result["after"]
    result["time_reduction_percent"] = 100 * (1 - a["time"]["mean"] / b["time"]["mean"])
    result["allocation_reduction_percent"] = 100 * (1 - a["allocation"]["mean"] / b["allocation"]["mean"])
    result["time_intervals_overlap"] = not (a["time"]["confidence_99_9"][1] < b["time"]["confidence_99_9"][0]
                                              or b["time"]["confidence_99_9"][1] < a["time"]["confidence_99_9"][0])
    return result


rows = []
for workload in WORKLOADS:
    source = args.prefix + "-" + workload + ".json"
    entries = json.loads((ROOT / source).read_text())
    assert all(r["params"]["workload"] == workload and r["params"]["sink"] == "heartbeat"
               and r["params"]["namespaceLayout"] == "stable" for r in entries)
    rows.append(pair(entries, workload, "ns/row and B/row", source))
small_rows = []
if args.include_small:
    source = args.prefix + "-small.json"
    entries = json.loads((ROOT / source).read_text())
    assert len(entries) == 6 and all(r["params"]["sink"] == "memory" for r in entries)
    for count in (0, 1, 8):
        small_rows.append(pair([r for r in entries if r["params"]["rows"] == str(count)],
                               str(count) + " rows", "ns/document and B/document", source))
memory_rows = []
if args.include_memory:
    source = args.prefix + "-memory.json"
    entries = json.loads((ROOT / source).read_text())
    assert len(entries) == 4 and all(r["params"]["sink"] == "memory" for r in entries)
    for workload in ("ascii", "long_unicode"):
        memory_rows.append(pair([r for r in entries if r["params"]["workload"] == workload],
                                workload, "ns/row and B/row", source))
source_path = "core/queryresultio/binary/src/main/java/org/eclipse/rdf4j/query/resultio/binary/BinaryQueryResultWriter.java"
report = {"published_baseline": "741b9389538e80214075692439a8cd25a8a9ae84",
          "production_source_sha256": hashlib.sha256((REPO / source_path).read_bytes()).hexdigest(),
          "large_document_rows": 4096, "forks": 2, "warmup_iterations": 5, "measurement_iterations": 5,
          "iteration_seconds": 1, "rows": rows, "small_documents": small_rows, "memory_control": memory_rows,
          "notes": ["Means and 99.9% intervals are the original JMH statistics, not recomputed significance claims.",
                    "Each workload was measured in a separate invocation; requested implementation order alternated by workload.",
                    "Shared-host timing and two forks limit generalization; inspect raw samples and fork means.",
                    "JFR timings and exploratory screens are excluded.",
                    "Positive reduction means less time/allocation; negative means more."]}
(ROOT / (args.prefix + "-results.json")).write_text(json.dumps(report, indent=2) + "\n")
lines = ["# Final production comparison", "", "Baseline: published commit `741b9389538e80214075692439a8cd25a8a9ae84`.", "",
         "Two fresh JVM forks per implementation, five one-second warmup and five one-second measurement iterations; one thread. "
         "The large-document table uses the actual heartbeat payload wrapper and stable namespaces. JFR and exploratory timings are excluded.", ""]

def table(title, items, unit):
    lines.extend(["## " + title, "", f"| Workload | Before, µs/{unit} | After, µs/{unit} | Time reduction | Before, B/{unit} | After, B/{unit} |",
                  "| --- | ---: | ---: | ---: | ---: | ---: |"])
    for r in items:
        b, a = r["before"], r["after"]
        lines.append(f"| [{r['workload']}]({r['source']}) | {b['time']['mean']/1000:.3f} | {a['time']['mean']/1000:.3f} | "
                     f"{r['time_reduction_percent']:.1f}% | {b['allocation']['mean']:.3f} | {a['allocation']['mean']:.3f} |")
    lines.extend(["", "### Timing uncertainty and fork means", "",
                  f"All values below are µs/{unit}. The ± values are JMH’s 99.9% confidence errors. "
                  "Intervals are descriptive; overlapping intervals and host variability preclude treating every point estimate as a demonstrated gain.", "",
                  "| Workload | Before mean ± error | After mean ± error | Before fork means | After fork means | Intervals overlap |",
                  "| --- | ---: | ---: | --- | --- | --- |"])
    for r in items:
        b, a = r["before"]["time"], r["after"]["time"]
        fmt = lambda values: ", ".join(f"{v/1000:.3f}" for v in values)
        lines.append(f"| {r['workload']} | {b['mean']/1000:.3f} ± {b['error_99_9']/1000:.3f} | "
                     f"{a['mean']/1000:.3f} ± {a['error_99_9']/1000:.3f} | {fmt(b['fork_means'])} | {fmt(a['fork_means'])} | "
                     f"{'yes' if r['time_intervals_overlap'] else 'no'} |")
    lines.append("")

table("Large documents: 4,096 rows", rows, "row")
if small_rows:
    table("Small documents: memory sink", small_rows, "document")
if memory_rows:
    table("Large-document memory-sink control", memory_rows, "row")
lines.extend(["## Interpretation", "", "The query workload includes native query evaluation and serialization. Synthetic fixtures preconstruct their input values. "
              "Long workloads encode different numbers of bytes, so comparisons are within each workload. "
              "Allocation includes other model and document costs; it is not a count of encoder bytes alone.", "",
              "Complete raw samples, source hashes and exact commands are preserved beside this report. "
              "See `methodology-review.md` and `REPRODUCING.md` for scope and reproduction.", ""])
(ROOT / (args.prefix + "-results.md")).write_text("\n".join(lines))
print("Wrote", args.prefix + "-results.json", "and", args.prefix + "-results.md")
